fn main() {
    println!("i8 {} {} {}", i8::MIN, -1i8, i8::MAX);
    println!("i16 {} {}", i16::MIN, i16::MAX);
    println!("i32 {} {} {}", i32::MIN, 0i32, i32::MAX);
    println!("i64 {} {}", i64::MIN, i64::MAX);
    println!("i128 {} {}", i128::MIN, i128::MAX);
    println!("isize {} {}", isize::MIN, isize::MAX);
    println!("u8 {} {}", u8::MIN, u8::MAX);
    println!("u16 {}", u16::MAX);
    println!("u32 {}", u32::MAX);
    println!("u64 {}", u64::MAX);
    println!("u128 {}", u128::MAX);
    println!("usize {}", usize::MAX);
}
